using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text.Json;
using BARANG.Core.Application.Orders;
using BARANG.Core.Application.Pricing;
using BARANG.Core.Domain.Catalog;
using BARANG.Core.Domain.Customers;
using BARANG.Core.Domain.Organization;
using BARANG.Core.Infrastructure.Persistence;
using Xunit;
using Domain = BARANG.Core.Domain;

namespace BARANG.Core.IntegrationTests.Database;

[Collection(PostgreSqlDatabaseFixture.CollectionName)]
public sealed class PricingE2ETests(PostgreSqlDatabaseFixture database)
{
    [Fact]
    public async Task AuthenticatedPricingFlowCalculatesFinalizesAndPreservesHistory()
    {
        CancellationToken ct=TestContext.Current.CancellationToken;await database.ResetAsync(ct);Guid company=Guid.NewGuid(),other=Guid.NewGuid(),branch=Guid.NewGuid(),customer=Guid.NewGuid();DateTimeOffset now=DateTimeOffset.UtcNow;Product product;ProductVariant variant;
        await using(CoreDbContext db=database.CreateAdministrationCoreDbContext()){db.Companies.AddRange(Company.Create(company,"PRICE_E2E","Pricing E2E",now).Value,Company.Create(other,"PRICE_OTHER","Pricing Other",now).Value);db.Branches.Add(Branch.Create(branch,company,"MAIN","Main",now).Value);db.Customers.Add(Customer.Create(customer,company,"PRICE-CUSTOMER",CustomerType.Organization,null,null,null,"Pricing Buyer",null,null,null,null,null,null,null,now).Value);product=Product.Create(Guid.NewGuid(),company,"PRICE-P","Pricing Shirt",null,"APPAREL","PCS",now).Value;variant=ProductVariant.Create(Guid.NewGuid(),product,"PRICE-SKU","Blue",null,"L","BLUE",now).Value;db.Add(product);db.Add(variant);await db.SaveChangesAsync(ct);}
        await using PostgreSqlCoreApiFactory factory=new(database.ConnectionString);using HttpClient client=factory.CreateClient();using HttpRequestMessage bootstrap=new(HttpMethod.Post,"/api/v1/security/bootstrap"){Content=JsonContent.Create(new{companyId=company,username="pricing-admin",displayName="Pricing Administrator",password="StrongPricingPassword123"})};bootstrap.Headers.Add("X-Bootstrap-Secret","test-bootstrap-secret-123456789");(await client.SendAsync(bootstrap,ct)).EnsureSuccessStatusCode();Login login=await Json<Login>(await client.PostAsJsonAsync("/api/v1/auth/login",new{username="pricing-admin",password="StrongPricingPassword123"},ct),ct);await Ok(client,Req(HttpMethod.Post,"/api/v1/auth/me/company",login.AccessToken,null,new{companyId=company}),ct);
        DateOnly from=new(2026,1,1);JsonDocument raw=await Tariff(0,"RAW",10,variant.Id,null,null);await Tariff(1,"FRONT_SCREEN",3,null,"FRONT","SCREEN");await Tariff(2,"DEFAULT",2,null,null,null);await Tariff(3,"DEFAULT",4,null,null,null);await Tariff(5,"RUSH",1,null,null,null);JsonDocument tariffList=await Json<JsonDocument>(await client.SendAsync(Req(HttpMethod.Get,"/api/v1/pricing/tariffs",login.AccessToken,company),ct),ct);Assert.Equal(5,tariffList.RootElement.GetArrayLength());await Ok(client,Req(HttpMethod.Post,"/api/v1/pricing/tax-rules",login.AccessToken,company,new{code="DEFAULT",ratePercent=9,isExempt=false,validFrom=from}),ct);
        OrderView draft=await Json<OrderView>(await client.SendAsync(Req(HttpMethod.Post,"/api/v1/orders",login.AccessToken,company,new{branchId=branch,customerId=customer,source="Internal",orderDate="2026-08-31"}),ct),ct);OrderItemView item=await Json<OrderItemView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/items",login.AccessToken,company,new{productId=product.Id,productVariantId=variant.Id,quantity=2}),ct),ct);await Ok(client,Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/items/{item.Id}/print-operations",login.AccessToken,company,new{sequence=1,printPositionCode="FRONT",printMethodCode="SCREEN",width=10,height=10}),ct);
        draft=await Json<OrderView>(await client.SendAsync(Req(HttpMethod.Get,$"/api/v1/orders/{draft.Id}",login.AccessToken,company),ct),ct);OrderPricingView calculated=await Json<OrderPricingView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/pricing/recalculate-with-manual-discount",login.AccessToken,company,new{orderVersion=draft.Version,discount=new{type=1,value=10,reason="authorized test"}}),ct),ct);Assert.Equal(33,calculated.Subtotal);Assert.Equal(3.30m,calculated.DiscountTotal);Assert.Equal(2.67m,calculated.TaxTotal);Assert.Equal(32.37m,calculated.FinalTotal);Assert.Single(calculated.Items);Assert.Equal(5,calculated.Components.Count(x=>x.Type is not (Domain.Pricing.PriceComponentType.Discount or Domain.Pricing.PriceComponentType.Tax)));
        using(HttpResponseMessage stale=await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/pricing/recalculate",login.AccessToken,company,new{orderVersion=draft.Version}),ct))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);draft=await Json<OrderView>(await client.SendAsync(Req(HttpMethod.Get,$"/api/v1/orders/{draft.Id}",login.AccessToken,company),ct),ct);OrderView submitted=await Json<OrderView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/submit",login.AccessToken,company,new{version=draft.Version}),ct),ct);OrderPricingView frozen=await Json<OrderPricingView>(await client.SendAsync(Req(HttpMethod.Get,$"/api/v1/orders/{draft.Id}/pricing",login.AccessToken,company),ct),ct);Assert.True(frozen.IsFinalized);Assert.NotNull(submitted.OrderNumber);JsonDocument updatedRaw=await Json<JsonDocument>(await client.SendAsync(Req(HttpMethod.Put,$"/api/v1/pricing/tariffs/{raw.RootElement.GetProperty("id").GetGuid()}",login.AccessToken,company,new{command=new{tariffType=0,code="RAW",productVariantId=variant.Id,amount=11,currencyCode="IRR",validFrom=from,version=raw.RootElement.GetProperty("version").GetInt64()},isActive=true}),ct),ct);Assert.Equal(11,updatedRaw.RootElement.GetProperty("amount").GetDecimal());
        await Tariff(3,"FUTURE",999,null,null,null,new DateOnly(2027,1,1));OrderPricingView unchanged=await Json<OrderPricingView>(await client.SendAsync(Req(HttpMethod.Get,$"/api/v1/orders/{draft.Id}/pricing",login.AccessToken,company),ct),ct);Assert.Equal(frozen.FinalTotal,unchanged.FinalTotal);using(HttpResponseMessage denied=await client.SendAsync(Req(HttpMethod.Get,$"/api/v1/orders/{draft.Id}/pricing",login.AccessToken,other),ct))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);await Ok(client,Req(HttpMethod.Post,"/api/v1/auth/logout",login.AccessToken,null),ct);

        async Task<JsonDocument> Tariff(int type,string code,decimal amount,Guid? variantId,string? position,string? method,DateOnly? validFrom=null)=>await Json<JsonDocument>(await client.SendAsync(Req(HttpMethod.Post,"/api/v1/pricing/tariffs",login.AccessToken,company,new{tariffType=type,code,productVariantId=variantId,printPositionCode=position,printMethodCode=method,amount,currencyCode="IRR",validFrom=validFrom??from}),ct),ct);
    }
    private static HttpRequestMessage Req(HttpMethod method,string uri,string token,Guid? company,object? body=null){HttpRequestMessage r=new(method,uri);r.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);if(company is not null)r.Headers.Add("X-Company-ID",company.ToString());if(body is not null)r.Content=JsonContent.Create(body);return r;}
    private static async Task Ok(HttpClient client,HttpRequestMessage request,CancellationToken ct){using HttpResponseMessage response=await client.SendAsync(request,ct);Assert.True(response.IsSuccessStatusCode,$"{response.StatusCode}: {await response.Content.ReadAsStringAsync(ct)}");}
    private static async Task<T> Json<T>(HttpResponseMessage response,CancellationToken ct){using(response){string payload=await response.Content.ReadAsStringAsync(ct);Assert.True(response.IsSuccessStatusCode,$"{response.StatusCode}: {payload}");return (await response.Content.ReadFromJsonAsync<T>(ct))!;}}
    private sealed record Login(string AccessToken);
}
